import{_ as o}from"./chunks/b2e3a757c59128641c28.Bk7yqlH3.js";import{_ as r,C as t,o as l,c as i,j as a,a as s,E as n,a6 as h}from"./chunks/framework.CnPv4DE1.js";const x=JSON.parse('{"title":"如何每天用12小时专注于你的使命","description":"","frontmatter":{"title":"如何每天用12小时专注于你的使命","originalTitle":"How To Focus For 12 Hours A Day On Your Purpose","date":"2024-10-05","originalUrl":"https://thedankoe.com/letters/how-to-focus-for-12-hours-a-day-on-your-purpose/","minutes":11,"sourceHash":"23b6af57aaec280cda56a0f895457009a48c64200dcbcdcc21784132bc969eb5","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-focus-for-12-hours-a-day-on-your-purpose/"}]]},"headers":[],"relativePath":"letters/how-to-focus-for-12-hours-a-day-on-your-purpose.md","filePath":"letters/how-to-focus-for-12-hours-a-day-on-your-purpose.md"}'),c={name:"letters/how-to-focus-for-12-hours-a-day-on-your-purpose.md"};function u(d,p,f,_,m,b){const e=t("ArticleMeta");return l(),i("div",null,[p[0]||(p[0]=a("h1",{id:"如何每天用12小时专注于你的使命",tabindex:"-1"},[s("如何每天用12小时专注于你的使命 "),a("a",{class:"header-anchor",href:"#如何每天用12小时专注于你的使命","aria-label":'Permalink to "如何每天用12小时专注于你的使命"'},"​")],-1)),n(e),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/gRIK2BYMrrc?si=wcwpYioM0j50uF5O" target="_blank" rel="noreferrer">观看原文视频</a></p><p>你不会在平庸的生活方式中找到罕见的成果。</p><p>如果你感到迷失、疲惫,无法专注于向你曾向自己承诺要过的那种生活迈进,有时你唯一能做的事,就是按下那个开关。</p><p>在矩阵中制造一个故障。</p><p>变成一个完全不同的人。</p><p>一次性改变你的习惯。清除生活中所有的干扰。开始创业。着手项目。每天工作12小时,忘了吃饭。回头一看,你会发现自己在3个月内完成的事,比过去3年做的还多。</p><p>你需要一段段高强度的季节,把你推向一个全新的基线。</p><p>凌晨4点起床能给你3到4个小时的体验,是别人根本没机会拥有的。那是一个完全不同的现实。一个安静的现实。人们都还没醒。干扰失去了它们的引力。</p><p>我不是说你必须凌晨4点起床。那只是一个拥抱非传统生活的例子。</p><p>但如果你的脑子已经在抵触打破那个令人痛苦的舒适泡泡这个想法,那你大概不会从这封信剩下的部分中获益。</p><p>打开你的思维,或者离开。</p><h3 id="你已经拥有动力" tabindex="-1">你已经拥有动力 <a class="header-anchor" href="#你已经拥有动力" aria-label="Permalink to &quot;你已经拥有动力&quot;">​</a></h3><p>事情是这样的。</p><p>你已经能够每天专注12个小时了。</p><p>当你在玩电子游戏或刷手机时,那是自动发生的。你根本不需要靠自律去做这件事。</p><p>但你内心深处知道,你正在毁掉自己的人生。</p><p>所以,我们需要学会如何创造一种心理、身体和精神层面的环境,让你为梦想努力这件事变得毫不费力、水到渠成。</p><p>首先,我们需要明白,12小时工作日并不总是可行的。你需要处于人生正确的阶段(而且你不能被困在任何一个阶段里出不来)。</p><p>其次,我们需要清除那些阻碍你把生活看作一场游戏的障碍。一场让人上瘾又好玩的游戏。一场你埋头苦干许多小时,却能在生活中看到真实进展的游戏。</p><p>如果你想彻底改变人生的方向,请继续读下去。</p><h2 id="进步的周期" tabindex="-1">进步的周期 <a class="header-anchor" href="#进步的周期" aria-label="Permalink to &quot;进步的周期&quot;">​</a></h2><p>很多人知道我的4小时工作日理念。</p><p>也有一些人——虽然人数较少,因为大多数人并不理解这个理念,他们只是看到这个想法就死死抓住——知道我并不喜欢一辈子坚持做同一件事,因为那会限制成长和探索。</p><p>进步是非线性的。</p><p>你不会连续10年去健身房,每年都增长同样多的肌肉。刚开始的时候你会长得很快,因为你是新手。之后,你会在一轮又一轮的自律与高强度周期中增肌。你会增肌然后减脂。生活会发生变故,让你脱离轨道整整一年。第二年你重新找回动力,变得极度自律,第10年获得的进步比第3年还多。</p><p>生产力也是同样的道理。</p><p>我不认为12小时的工作日是可以永远持续下去的事。那样想简直愚蠢。它的弊端显而易见:倦怠、忽视生活的其他领域,以及,单纯地,没有什么可以继续做下去的事情了。</p><p>12小时工作日不应该被强迫执行。</p><p>任何工作量都不该被强迫。</p><p>如果它是被强迫的,那就改变你的工作(或者改变你的心态)。</p><p>就像狮子捕猎后要休息一样,我们要在自己的工作中复制这种模式。</p><h3 id="_1-迷茫" tabindex="-1">1)迷茫 <a class="header-anchor" href="#_1-迷茫" aria-label="Permalink to &quot;1)迷茫&quot;">​</a></h3><p><img src="'+o+'" alt=""></p><p>进步有4个周期。</p><p>你可以把这些周期想象成一本书的各个章节。</p><p>第一个周期是迷茫,也就是感到迷失和困惑。</p><p>你处在故事的开端。你还没有设定场景,也没有找到自己的使命。</p><p>你无法工作12小时,因为你没有值得投入的事情。你不知道接下来该做什么。</p><p>大多数人都处在这个周期里。他们被困住了。他们不允许自己感到无聊,于是用即时满足和廉价的多巴胺淹没自己的大脑。这很糟糕,因为它会欺骗你的大脑,让你以为自己在取得进展。显而易见,这就是为什么你没有那种天然的渴望去追求更高的东西。</p><p>你要靠变得好奇来逃出迷茫这个周期。</p><p>如果你在这方面有困难,我们会在下一节讨论进步的阻碍因素。</p><h3 id="_2-好奇" tabindex="-1">2)好奇 <a class="header-anchor" href="#_2-好奇" aria-label="Permalink to &quot;2)好奇&quot;">​</a></h3><p>在你构建梦想人生这本书里,下一章是好奇。</p><p>你识别出生活中的一个问题。</p><p>你深入挖掘它是如何把你拖入混乱的。</p><p>工作。账单。疲乏无力。身材不佳。社交能力欠缺。不管是什么。你有大把的问题可以去解决。只是你被分散了注意力。</p><p>你变得好奇,渴望找到解决方案。</p><p>在这个阶段,你的思维会经历一次关键的视角转变。</p><p>你开始注意到那些强化一个新目标、试图重塑你身份认同的信息。</p><p>你开始让自己接触新的环境。</p><p>举个例子,如果你对自己的工作——它用超长工时和低薪拖累了你生活中的每一个其他领域——感到厌恶,你就会开始在社交媒体上注意到商业机会,或者开始搜索可以尝试的副业,又或者你终于决定开始投资或做预算。</p><p>在好奇阶段,你的任务就是尝试一切,看看什么能让你坚持下去。</p><p>“闪光物综合症”(Shiny object syndrome,见异思迁)其实是一件好事。</p><p>但前提是,它要朝着一个对你未来有积极意义的方向。</p><p>多读书。加入新的数字社交圈。看新的内容。买课程。做项目。什么都试一试。让各种想法在你脑中不断积累,直到你获得刚好足够的清晰度,可以全情投入到那件你根本无法把自己从中拉开的事情上。</p><p>然后,进入一段高强度的季节。</p><h3 id="_3-高强度" tabindex="-1">3)高强度 <a class="header-anchor" href="#_3-高强度" aria-label="Permalink to &quot;3)高强度&quot;">​</a></h3><p>故事的高潮。</p><p>主要的战斗。</p><p>你人生中最有趣、最充实的部分。</p><p>这3到6个月一晃而过。纯粹的心流状态。完全专注于实现一个有意义的目标。</p><p>在健身领域,这是你在饮食和训练上极度自律的时候。你脑子里想的全是这件事。</p><p>在感情关系中,这就是热恋期。你想做的一切,就是和一个人建立连接。</p><p>在生意上,这是打造并推出一款新产品,或者进入一段疯狂写作的时期。两者都会带来增长和收入上的新高度。</p><p>这就是你拉出12小时工作日的时候。</p><p>想在其他任何阶段强行做到这一点,都很愚蠢。你最终只会一边产出低质量的工作,一边让生活其他领域悄悄滑坡。</p><p>当然,这个阶段也很快会变得危险。</p><p>你必须知道何时该退出这个阶段。你也必须知道如何从你所建立的那些新习惯中过渡出来。</p><p>不要把增肌期硬推到变胖的程度。</p><p>不要把减脂期硬推到瘦骨如柴、掉肌肉的程度。</p><p>不要在一段关系里痴迷到变得粘人和患得患失。</p><p>不要一味想把收入推得更高,结果毁掉了自己的品牌声誉。</p><p>要知道何时该降到一个新的基线,并维持住你已经取得的进步。</p><h3 id="_4-持续" tabindex="-1">4)持续 <a class="header-anchor" href="#_4-持续" aria-label="Permalink to &quot;4)持续&quot;">​</a></h3><p>不,持续并不是万能的。</p><p>持续是一种维持进步的工具,而不是创造进步的工具。</p><p>停滞不等于维持进步。停滞就是死亡。</p><p>内容创作上的持续本身并不会带你去任何地方。你必须变得好奇,去尝试新的角度和策略。当你找到正确的那个,你就要加大投入,看到你所能看到的最大增长(这就是我如何在几个月内在YouTube上增长20万粉、在同期在Instagram上增长120万粉的原因)。你找到一个策略,然后充分挤出它的价值。但要意识到,那些策略不会永远有效。无常。</p><p>在你的工作中,持续阶段就是你把工作量降到每天4小时的高优先级工作。这个时间,足够你为下一个高强度阶段做实验,也足够你维持比上一个宏观周期更高的基线。</p><p>当我在一次产品发布后,月收入一下冲到70万美元时,我根本没办法维持那样的水平。倒不是说我完全不可能做到,只是我当时没有合适的基础设施来撑住那个水平。相反,它把我带到了一个新的、更高的基线,而我确保自己执行了维持这个水平所必需的那些优先任务。</p><p>对我的工作来说,那些任务是:每天写作2小时,再花一到两个小时管理业务,以及打造像书籍或产品这样的新项目,一直坚持到下一个高强度季节的到来。</p><p>这个持续周期非常重要。</p><p>当生活变得忙碌时,它就是你降低强度、维持健身房里已有成果的方式。它也是当那种神经化学的“鸡尾酒”效应褪去后,你用来经营一段关系的方式。</p><p>关键在于——如果你还没有经历过其他的周期,你根本没有什么值得去“持续”的东西。</p><p>如果你被困在迷失感的周期里,那是因为你的思维被堵住了。</p><h2 id="为什么你无法轻松地每天专注12个小时" tabindex="-1">为什么你无法轻松地每天专注12个小时 <a class="header-anchor" href="#为什么你无法轻松地每天专注12个小时" aria-label="Permalink to &quot;为什么你无法轻松地每天专注12个小时&quot;">​</a></h2><p>我们别浪费时间了。</p><p>你无法专注,正是因为你的思维、生活和优先事项一片混乱。</p><p>而你对此什么也没做。</p><h3 id="_1-清除专注的阻碍" tabindex="-1">1)清除专注的阻碍 <a class="header-anchor" href="#_1-清除专注的阻碍" aria-label="Permalink to &quot;1)清除专注的阻碍&quot;">​</a></h3><p>专注,就是清除一切阻碍专注的东西。</p><p>你感到迷失、分心、精力低下,正是因为这个原因。</p><p>你一感到无聊,就用最容易得到的东西去填补它。</p><p>你一感到焦虑,也会做同样的事。</p><p>你的思维正在引导你走向一个更好的人生,但你没有去倾听那些信号,反而试图去麻痹那种“我没有成为自己本可以成为的那个人”所带来的痛苦,而从长远来看,这只会让情况更糟。</p><p>有几个阻碍因素,让你一直感到迷失:</p><p><strong>使命</strong></p><p>你感到迷失,是因为你缺乏使命。</p><p>你不知道自己在解决什么问题。你不知道自己在追求什么目标。你不知道自己在一个比你自身更宏大的整体中扮演什么角色。</p><p>你的思维被训练成去专注于社会分配给你的那些目标。你的路早就被规划好了。上学,找工作,退休。你最终拖着脚步走过人生,感到无聊,因为你根本不在乎那些东西。你用懒散和感官享乐来填补自己的无聊,而不是朝着自己的目标去建设什么。</p><p>你需要允许自己去感到无聊。</p><p>你需要让自己接触更高的可能性。</p><p>你需要放下一切,看看什么能真正留下来。</p><p>你需要与自己的思绪静静相处,这样你才能捕捉到愿景的一丝苗头。</p><p><strong>环境</strong></p><p>你的环境塑造了你是谁。</p><p>但大多数人都忘了,他们对自己的环境拥有完全的掌控权。</p><p>如果你在物理世界和数字世界中都被人群、各种观点和干扰所包围,那你无法专注也就毫不奇怪了。</p><p>把绷带一把撕掉。</p><p>抽出一天时间,几乎是字面意义上地,把一切(1)不重要的、以及(2)会让你从重要事情上分心的东西统统扔掉。别犹豫。</p><p><strong>代谢</strong></p><p>你缺乏动力,是因为你一次吃太多东西。</p><p>作为一个225磅(约102公斤)重的人,如果我在白天的一顿正餐里摄入超过300到600卡路里,我的专注力就会受到严重影响。</p><p>试试间歇性禁食。</p><p>试试少吃几顿小餐,把晚餐吃大一些。</p><p>如果你吃得太多,你的身体就会从你原本可以用于专注的能量中抽走一部分,投入到消化过程中。</p><p>等工作完成后,用一顿大餐来奖励自己。</p><p><strong>知识</strong></p><p>你迷失了方向,是因为你不知道<em>现在此刻</em>该做什么。</p><p>你把自己投射到那个你想要的未来里,卡在那里,然后开始为这段旅程会有多漫长、多艰难而焦虑。</p><p>如果你迷失了,就去学习。</p><p>当你有了方向,就去行动。</p><p>别在该学习的时候试图去行动,也别在该行动的时候还在学习。仅这一点,就能解决你99%的方向不清问题。</p><h3 id="_2-把你的思维推向深渊边缘" tabindex="-1">2)把你的思维推向深渊边缘 <a class="header-anchor" href="#_2-把你的思维推向深渊边缘" aria-label="Permalink to &quot;2)把你的思维推向深渊边缘&quot;">​</a></h3><p>一切都始于身份认同。</p><p>那张塑造你如何看待这个世界的观念之网。</p><p>这种视角是由几十年的社会训导塑造出来的,它让你渴望你所渴望的东西。</p><p>如果你想热爱为梦想努力的过程,你的思维必须体现这一点。</p><p>它不能只是一个你听起来喜欢的想法。它必须是<em>你是谁。</em></p><p>你要如何改变你是谁?</p><p>重新编程你的大脑。</p><p>把自己从当前的生活方式中抽离出来,沉浸在那些能慢慢塑造你看待世界方式的信息中。</p><p>在社交媒体上关注那些拥有你想追求的目标的人。</p><p>听播客、读书,用真金白银购买课程,让钱花在你说的话上——这些课程会慢慢给你想法,这些想法会累积成清晰感。</p><p>明天醒来,什么都别和以前一样。</p><p>规划新的一周。设定新的优先任务。进行新的对话。让自己被新信息淹没。</p><h3 id="_3-想得更大-做得更小" tabindex="-1">3) 想得更大,做得更小 <a class="header-anchor" href="#_3-想得更大-做得更小" aria-label="Permalink to &quot;3) 想得更大,做得更小&quot;">​</a></h3><p>你现在处于一种混乱的状态。</p><p>创造秩序是你的责任。</p><p>你被新想法包围,可以把它们收集起来作为你愿景的构建砖块。然后,你可以一天又一天地铺设这些砖块,创造你想要的生活。</p><p>你需要一个愿景。没有它,从定义上讲,你就是迷失的。</p><p>拿出一张纸,写下:</p><ul><li>你厌恶的、不想再出现在你生活中的一切(反愿景)。</li><li>你想要的未来的一切。身体。生活方式。地点。心智。金钱。任何事物。别担心显得肤浅。你可以以后从中创造意义。</li></ul><p>在<a href="https://bootcamp.kortex.co/" target="_blank" rel="noreferrer">写作训练营(Writer&#39;s Bootcamp)</a>内部,这个确切的过程会成为你的品牌。你所有的写作主题都源于此。</p><p>你会每周回到这个过程。</p><p>随着时间推移,你的愿景会变得越来越清晰。</p><p>在你经历这个过程时,你在等待“灯泡一亮”的那一刻发生。</p><p>那个一切都豁然开朗的瞬间,你会进入一个高强度的阶段。</p><p>但愿景并不是拼图的唯一一块。</p><p>大目标是为了激励、视角和潜力。</p><p>小目标是为了清晰、行动和心智健全。</p><h3 id="_4-逆向工程你的优先事项" tabindex="-1">4) 逆向工程你的优先事项 <a class="header-anchor" href="#_4-逆向工程你的优先事项" aria-label="Permalink to &quot;4) 逆向工程你的优先事项&quot;">​</a></h3><p>一旦你有了最小可行愿景,就这样做。</p><p>把它分解为:</p><ul><li>10年目标</li><li>1年目标</li><li>月度目标</li><li>周目标</li><li>每日优先任务</li></ul><p>然后,只专注于优先任务。</p><p>其他一切都是为了清晰。</p><p>你需要测试自己完成多少优先任务,什么时候完成它们,以及如何构建你的工作。</p><p>我个人喜欢2小时的工作区块。</p><p>我通常能在这段时间内完成1到3项任务。</p><p>在区块之间,我散步、去健身房、吃午饭,偶尔读书。这让我的一天更容易消化。</p><h3 id="_5-每周完善你的效率系统" tabindex="-1">5) 每周完善你的效率系统 <a class="header-anchor" href="#_5-每周完善你的效率系统" aria-label="Permalink to &quot;5) 每周完善你的效率系统&quot;">​</a></h3><p>在每周开始时,我会做一次周复盘。</p><ul><li>上周哪些事进展顺利?</li><li>哪些事没有进展顺利?</li><li>我感激什么?</li><li>我的重点项目是什么?</li></ul><p><a href="https://app.kortex.co/public/document/883d9246-6dde-4794-9f54-92b8ff07d502" target="_blank" rel="noreferrer">如果你想把它复制到你的工作区,我用的是这个Kortex模板。</a></p><p>如果你没有访问权限,加入等候名单,你很快就会收到它。</p><p>简单直接,你可以在5分钟内完成。</p><p>这一步很重要。它能揭示出(1)你应该在愿景和反愿景中添加什么,以及(2)本周可以做出哪些小改动以获得更好的结果。</p><p>如果你坚持这个过程,你会对自己在6到12个月内走了多远感到震惊。</p><p>——丹</p><hr><p><a href="/en/letters/how-to-focus-for-12-hours-a-day-on-your-purpose">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',172))])}const P=r(c,[["render",u]]);export{x as __pageData,P as default};
